import{_ as a,c as n,o as t,ai as r}from"./chunks/framework.DCS7ajmO.js";const u=JSON.parse('{"title":"Gardener Hackathon","description":"","frontmatter":{"title":"Gardener Hackathon","date":"2026-11-09","banner":"assets/events/20261109_gardener_hackathon_november_banner.svg","bannerMobile":"assets/events/20261109_gardener_hackathon_november_banner_mobile.svg","bannerSmall":"assets/events/20261109_gardener_hackathon_november_banner_small.svg","backgroundhex":"#889aa4ff","tags":["neonephos","hackathon"],"rssPubDate":"2026-09-09","published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"EventEntryThemeComponent"},"headers":[],"relativePath":"events/2026_11_09_gardener_hackathon_november.md","filePath":"events/2026_11_09_gardener_hackathon_november.md"}'),o={name:"events/2026_11_09_gardener_hackathon_november.md"};function s(h,e,i,c,d,p){return t(),n("div",null,e[0]||(e[0]=[r('<h2 id="hack-the-garden-11-2026" tabindex="-1">Hack The Garden 11/2026 <a class="header-anchor" href="#hack-the-garden-11-2026" aria-label="Permalink to &quot;Hack The Garden 11/2026&quot;">​</a></h2><p><strong>Hack The Garden 11/2026</strong> brings together contributors, maintainers, and users from across the Gardener ecosystem for several days of focused collaboration, hands-on development, and community building.</p><p>The event is intentionally kept small, with a maximum of 28 participants, creating an environment where attendees can work closely together on real challenges, share knowledge, and actively contribute to the future of the project.</p><h3 id="neonephos-and-hack-the-garden" tabindex="-1">NeoNephos and Hack The Garden <a class="header-anchor" href="#neonephos-and-hack-the-garden" aria-label="Permalink to &quot;NeoNephos and Hack The Garden&quot;">​</a></h3><p>We are pleased that the <strong>NeoNephos Foundation</strong> is supporting this edition of Hack The Garden by sponsoring half of the event costs.</p><p>Supporting community-driven events such as Hack The Garden helps strengthen the open-source ecosystem around Gardener and related infrastructure projects. It also creates opportunities for maintainers, contributors, and adopters to collaborate directly, exchange ideas, and shape future development priorities together.</p><p>As one of the key projects within the NeoNephos ecosystem, Gardener plays an important role in enabling open, interoperable, and cloud-native infrastructure. Investing in its community helps foster long-term sustainability, trust, and collaboration across the ecosystem.</p><p>Whether you are an experienced contributor or looking to become more engaged with the Gardener community, Hack The Garden offers a unique opportunity to connect with peers and work together on the future of open infrastructure.</p><hr><p>📍 Schlosshof, Germany</p><p>📅 November 2026</p><p>🔗 <a href="https://gardener.cloud/community/hackathons/2026-11/" target="_blank" rel="noreferrer">Learn more about the hackathon</a></p><p>🔗 <a href="https://gardener.cloud/community/hackathons" target="_blank" rel="noreferrer">Previous hackathons and what to expect</a></p>',13)]))}const _=a(o,[["render",s]]);export{u as __pageData,_ as default};
